// Purpose: Pauses, resumes, or stops future Voice Relay dispatches at the StreamBridge queue.
// References: mscorlib.dll, System.dll, netstandard.dll, Newtonsoft.Json.dll.
using System; using Newtonsoft.Json.Linq;
